CHECK_EQ(core_init(), 1);
unsigned char fr[64];
int flen = core_frame("hello", 5, fr, sizeof fr);
CHECK_EQ(flen, 9);
char back[64] = {0};
int ulen = core_unframe(fr, (size_t)flen, back, sizeof back);
CHECK_EQ(ulen, 5);
CHECK_STR_EQ(back, "hello");

unsigned char fr3[16] = {255, 255, 255, 255, 104, 105};
char out3[16] = {0};
CHECK_EQ(core_unframe(fr3, 6, out3, sizeof out3), -1);

unsigned char frn[64];
char backn[64] = {0};
CHECK_EQ(core_frame(NULL, 5, frn, 64), -1);
CHECK_EQ(core_unframe(NULL, 9, backn, 64), -1);
